def primitive_axis(self, axis):
    self.primitive_axis_attempts += 1
    for coordinate in axis:
        self.checked(coordinate)
    self.tick()
    common = self.checked(math.gcd(*axis))
    self.largest_axis_divisor_bits = max(self.largest_axis_divisor_bits, common.bit_length())
    if common <= 1:
        return axis
    self.primitive_axis_reductions += 1
    return tuple(self.div(coordinate, common) for coordinate in axis)

